can you please post the ouput of the following PHP code:

``` php
echo PHP_VERSION . "\n";
echo INTL_ICU_VERSION . "\n";
```

Modify `I18N::format()` like the following and show output:

``` php
public function format($message, $params, $language)
{
    echo '<hr />';
    echo '<pre>-> '.print_r($message, true).'</pre>';
    echo '<pre>-> '.print_r($params, true).'</pre>';
    echo '<pre>-> '.print_r($language, true).'</pre>';
    if ($params instanceof Arrayable) {
        $params = $params->toArray();
    } else {
        $params = (array)$params;
    }
    if ($params === []) {
        echo '<pre>'.print_r($message, true).' -> 1</pre>';
        return $message;
    }

    if (preg_match('~{\s*[\d\w]+\s*,~u', $message)) {
        $formatter = $this->getMessageFormatter();
        $result = $formatter->format($message, $params, $language);
        if ($result === false) {
            $errorMessage = $formatter->getErrorMessage();
            Yii::warning("Formatting message for language '$language' failed with error: $errorMessage. The message being formatted was: $message.");
            echo '<pre>'.print_r($message, true).' -> 2</pre>';
            return $message;
        } else {
            echo '<pre>'.print_r($result, true).' -> 3</pre>';
            return $result;
        }
    }

    $p = [];
    foreach($params as $name => $value) {
        $p['{' . $name . '}'] = $value;
    }
    $message = strtr($message, $p);
    echo '<pre>'.print_r($message, true).' -> 4</pre>';
    return $message;
}
```

@tibee can you remove prevous debug code and instead replace `MessageFormatter::format` with the following and run it with commented and uncommented `hu-HU`:

``` php
public function format($pattern, $params, $language)
{
    echo '<hr />';
    echo '<pre>'.print_r('Arguments:', true).'</pre>';
    echo '<pre>'.print_r($pattern, true).'</pre>';
    echo '<pre>'.print_r($params, true).'</pre>';
    echo '<pre>'.print_r($language, true).'</pre>';

    $this->_errorCode = 0;
    $this->_errorMessage = '';

    if ($params === []) {
        return $pattern;
    }

    if (!class_exists('MessageFormatter', false)) {
        echo '<pre>'.print_r('Fallback!', true).'</pre>';
        return $this->fallbackFormat($pattern, $params, $language);
    }

    if (version_compare(PHP_VERSION, '5.5.0', '<') || version_compare(INTL_ICU_VERSION, '4.8', '<')) {
        echo '<pre>'.print_r('Low versions: PHP='. PHP_VERSION . ', ICU=' . INTL_ICU_VERSION, true).'</pre>';
        // replace named arguments
        $pattern = $this->replaceNamedArguments($pattern, $params, $newParams);
        $params = $newParams;
    }

    echo '<pre>'.print_r('Formatter input:', true).'</pre>';
    echo '<pre>'.print_r($pattern, true).'</pre>';
    echo '<pre>'.print_r($params, true).'</pre>';
    echo '<pre>'.print_r($language, true).'</pre>';

    $formatter = new \MessageFormatter($language, $pattern);
    if ($formatter === null) {
        $this->_errorCode = intl_get_error_code();
        $this->_errorMessage = "Message pattern is invalid: " . intl_get_error_message();
        return false;
    }
    $result = $formatter->format($params);
    if ($result === false) {
        $this->_errorCode = $formatter->getErrorCode();
        $this->_errorMessage = $formatter->getErrorMessage();
        return false;
    } else {
        return $result;
    }
}
